describe('Table Data Review - Table Rows and Columns', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/tables');
  });

  it('should display table with correct header and row count', () => {
    // Verify table exists
    cy.get('[data-testid="table-container"]').should('be.visible');

    // Verify table element exists
    cy.get('[data-testid="table-data"]').should('be.visible');

    // Verify table has a header row
    cy.get('[data-testid="table-header"]').should('be.visible');

    // Verify header contains correct column headings
    cy.get('[data-testid="table-header"]').within(() => {
      cy.get('th').should('have.length', 4);
      cy.get('th').first().should('contain', 'Last Name');
      cy.get('th').eq(1).should('contain', 'First Name');
      cy.get('th').eq(2).should('contain', 'Email');
      cy.get('th').eq(3).should('contain', 'Due');
    });

    // Verify table body contains 4 rows
    cy.get('[data-testid="table-body"]').within(() => {
      cy.get('tr').should('have.length', 4);
    });
  });

  it('should verify specific row data and column values', () => {
    // Verify table has at least one row
    cy.get('[data-testid="table-body"]').should('be.visible');

    // Verify the first row contains expected data
    cy.get('[data-testid="table-body tr:first-child"]').within(() => {
      cy.get('td').first().should('contain', 'Smith');
      cy.get('td').eq(1).should('contain', 'John');
      cy.get('td').eq(2).should('contain', 'jsmith@gmail.com');
      cy.get('td').eq(3).should('contain', '2023-10-15');
    });

    // Verify the last row contains expected data
    cy.get('[data-testid="table-body tr:last-child"]').within(() => {
      cy.get('td').first().should('contain', 'Johnson');
      cy.get('td').eq(1).should('contain', 'Jane');
      cy.get('td').eq(2).should('contain', 'johnson@example.com');
      cy.get('td').eq(3).should('contain', '2023-11-01');
    });

    // Verify all rows have 4 cells
    cy.get('[data-testid="table-body tr"]').each(($row) => {
      cy.wrap($row).within(() => {
        cy.get('td').should('have.length', 4);
      });
    });
  });
});
